CREATE TYPE public.app_role AS ENUM ('admin','analyst','viewer');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE TABLE public.shared_definitions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dataset_key text NOT NULL CHECK(dataset_key IN ('school','covid')), definition_key text NOT NULL, version integer NOT NULL DEFAULT 1, payload jsonb NOT NULL, approved_by uuid NOT NULL, approved_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.shared_definitions TO anon,authenticated;
GRANT INSERT ON public.shared_definitions TO authenticated;
GRANT ALL ON public.shared_definitions TO service_role;
ALTER TABLE public.shared_definitions ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_shared_definitions ON public.shared_definitions FOR SELECT TO anon,authenticated USING (true);
CREATE POLICY approve_shared_definitions ON public.shared_definitions FOR INSERT TO authenticated WITH CHECK (approved_by=auth.uid() AND (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'analyst')));
CREATE TABLE public.dataset_access (dataset_id uuid NOT NULL, user_id uuid NOT NULL, can_query boolean NOT NULL DEFAULT true, PRIMARY KEY(dataset_id,user_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.dataset_access TO authenticated;
GRANT ALL ON public.dataset_access TO service_role;
ALTER TABLE public.dataset_access ENABLE ROW LEVEL SECURITY;
CREATE POLICY view_dataset_access ON public.dataset_access FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_dataset_access ON public.dataset_access FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
COMMENT ON TABLE public.dataset_access IS 'Admin-managed grants for future private dataset querying; existing public datasets remain public.';